# region: sift
def sift(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: intake
def intake(xs, factor=10):
    return [v * factor for v in xs]

# region: render
def render(xs):
    return {'n': len(xs) - 1, 'total': sum(xs)}

# region: emit
def emit(summary, bar=3):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return emit(render(intake(sift(raw))))

